            {6'd49, 3'd1}: bits = 8'b00100000;  // '>'
            {6'd49, 3'd2}: bits = 8'b00010000;  // '>'
            {6'd49, 3'd3}: bits = 8'b00001000;  // '>'
            {6'd49, 3'd4}: bits = 8'b00010000;  // '>'
            {6'd49, 3'd5}: bits = 8'b00100000;  // '>'
            {6'd49, 3'd6}: bits = 8'b01000000;  // '>'
            default: bits = 8'b00000000;
        endcase
    end
endmodule
`default_nettype wire
